#include "zari/manager.hpp"
namespace zari {
Manager::Manager(fs::path p,Config c):config(std::move(c)){tabs.emplace_back(p);std::string e;if(!tabs[0].navigate(p,config.manager,e,false))throw std::runtime_error("cannot open "+p.string()+": "+e);}
Tab&Manager::tab(){return tabs[active];}const Tab&Manager::tab()const{return tabs[active];}void Manager::refresh(){tab().refresh(config.manager);}bool Manager::new_tab(){tabs.emplace_back(tab().directory);std::string e;if(!tabs.back().navigate(tab().directory,config.manager,e,false)){tabs.pop_back();return false;}active=tabs.size()-1;return true;}bool Manager::close_tab(){if(tabs.size()==1)return false;tabs.erase(tabs.begin()+static_cast<long>(active));if(active>=tabs.size())active=tabs.size()-1;return true;}void Manager::switch_tab(int d){active=static_cast<std::size_t>((static_cast<int>(active)+d+static_cast<int>(tabs.size()))%static_cast<int>(tabs.size()));}void Manager::direct_tab(std::size_t i){if(i<tabs.size())active=i;}
std::vector<fs::path>Manager::targets()const{if(!tab().selected.empty())return {tab().selected.begin(),tab().selected.end()};if(auto*c=tab().current())return{c->path};return{};}void Manager::set_clipboard(ClipMode m){clipboard=targets();clip_mode=m;}void Manager::clear_selection(){tab().selected.clear();}
bool Manager::paste(std::string&error){if(clipboard.empty()){error="clipboard is empty";return false;}for(const auto&p:clipboard){auto dst=collision_free(tab().directory/p.filename());bool ok=clip_mode==ClipMode::cut?move_path(p,dst,error):copy_path(p,dst,error);if(!ok)return false;}if(clip_mode==ClipMode::cut){clipboard.clear();clip_mode=ClipMode::none;}refresh();return true;}
}
